/** Practice follows real completed actions, not button presses, save cycles, or distant quarry. */
public final class SkillActionGameTests {
    public static void nativeBerryTiming(GameTestHelper h){
        var actor=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);var pos=h.absolutePos(new BlockPos(2,2,1));actor.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(pos.west()));h.getLevel().setBlock(pos.below(),Blocks.GRASS_BLOCK.defaultBlockState(),3);h.getLevel().setBlock(pos.east(),Blocks.WATER.defaultBlockState(),3);h.getLevel().setBlock(pos,Blocks.SWEET_BERRY_BUSH.defaultBlockState().setValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.AGE_3,3),3);var original=h.getLevel().getServer().getCommandStorage().get(SurvivalApi.CALENDAR).copy();try{long summer=dev.qube.spawn_9b5fbb9.Config.SEASON_DAYS.get()*24000L;var shifted=original.copy();shifted.putLong("sleepOffset",summer-h.getLevel().getServer().overworld().getLevelData().getGameTime());h.getLevel().getServer().getCommandStorage().set(SurvivalApi.CALENDAR,shifted);var hit=new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos),net.minecraft.core.Direction.UP,pos,false);var event=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(actor,InteractionHand.OFF_HAND,pos,hit);net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event);if(!event.isCanceled())h.getLevel().getBlockState(pos).useWithoutItem(h.getLevel(),actor,hit);int instant=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(2),e->e.getItem().is(Items.SWEET_BERRIES)).stream().mapToInt(e->e.getItem().getCount()).sum();h.assertTrue(event.isCanceled()&&WorldActions.inspectJob(actor).get("active").getAsBoolean()&&instant==0&&SurvivalApi.state(actor).skills.experience(Skill.FORAGING)==0,"Native berry use must begin shared timed work without instant berries or practice");h.assertTrue(h.getLevel().getBlockState(pos).getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.AGE_3)==3,"Starting harvest cannot prematurely consume berry recovery");finish(actor,200);h.assertTrue(h.getLevel().getBlockState(pos).getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.AGE_3)==1&&SurvivalApi.state(actor).skills.experience(Skill.FORAGING)==10.5,"Actual berry completion must reset the bush and award one wild-foraging practice");actor.tickCount++;net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.tick.EntityTickEvent.Post(actor));h.assertTrue(SurvivalApi.state(actor).skills.experience(Skill.FORAGING)==10.5,"No deferred native berry path may duplicate the timed completion award");}finally{h.getLevel().getServer().getCommandStorage().set(SurvivalApi.CALENDAR,original);}h.succeed();
    }
    public static void stationCancelSurface(GameTestHelper h){
        var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));actor.setNoAi(true);SurvivalApi.enroll(actor);var at=h.absolutePos(new BlockPos(2,1,1));h.getLevel().setBlock(at,SurvivalContent.KILN.get().defaultBlockState(),3);var station=(dev.qube.spawn_9b5fbb9.content.WorkstationEntity)h.getLevel().getBlockEntity(at);station.fuel=10000;var recipe=dev.qube.spawn_9b5fbb9.content.Production.RECIPES.get("fire_pot");var material=net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.parse(recipe.input()));actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(material,recipe.count()));h.assertTrue(dev.qube.spawn_9b5fbb9.content.Production.start(actor,station,"fire_pot").startsWith("Started"),"A real pottery job must reserve its physical clay input");h.assertTrue(WorldActions.cancel(actor,"Requested").success(),"Shared controller cancellation must reach an owned station when no world job is active");h.assertTrue(station.input.isEmpty()&&SurvivalApi.state(actor).skills.experience(Skill.POTTERY)==0,"Station cancellation must clear unfinished work without practice");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,actor.getBoundingBox().inflate(3),e->e.getItem().is(material)).stream().mapToInt(e->e.getItem().getCount()).sum()==recipe.count(),"Cancellation through the shared surface must return exactly the real reserved clay");actor.discard();h.succeed();
    }
    public static void nativeSowing(GameTestHelper h){
        var actor=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);var pos=h.absolutePos(new BlockPos(2,2,1));actor.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(pos.west()));h.getLevel().setBlock(pos.below(),Blocks.FARMLAND.defaultBlockState().setValue(FarmlandBlock.MOISTURE,7),3);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WHEAT_SEEDS));var original=h.getLevel().getServer().getCommandStorage().get(SurvivalApi.CALENDAR).copy();try{var spring=original.copy();spring.putLong("sleepOffset",-h.getLevel().getServer().overworld().getLevelData().getGameTime());h.getLevel().getServer().getCommandStorage().set(SurvivalApi.CALENDAR,spring);var event=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(actor,InteractionHand.MAIN_HAND,pos.below(),new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos.below()),net.minecraft.core.Direction.UP,pos.below(),false));net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(event);h.assertTrue(event.isCanceled()&&WorldActions.inspectJob(actor).get("active").getAsBoolean()&&actor.getMainHandItem().isEmpty(),"A native human seed interaction must reserve the real seed into shared timed work");h.assertTrue(SurvivalApi.state(actor).skills.experience(Skill.FARMING)==0,"Native sow initiation cannot grant practice");finish(actor,200);h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.WHEAT)&&SurvivalApi.state(actor).skills.experience(Skill.FARMING)==10.5,"A completed native seed interaction must place one real crop and award one sowing practice");
        h.getLevel().setBlock(pos,Blocks.AIR.defaultBlockState(),3);actor.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(Items.WHEAT_SEEDS));var offhand=new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.RightClickBlock(actor,InteractionHand.OFF_HAND,pos.below(),new net.minecraft.world.phys.BlockHitResult(net.minecraft.world.phys.Vec3.atCenterOf(pos.below()),net.minecraft.core.Direction.UP,pos.below(),false));net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(offhand);h.assertTrue(offhand.isCanceled()&&WorldActions.inspectJob(actor).get("active").getAsBoolean()&&actor.getOffhandItem().isEmpty(),"Offhand seeds must enter the same validated timed work rather than vanilla instant planting");finish(actor,200);h.assertTrue(h.getLevel().getBlockState(pos).is(Blocks.WHEAT)&&SurvivalApi.state(actor).skills.experience(Skill.FARMING)==21,"Both real hands must grant one completion award each");
        }finally{h.getLevel().getServer().getCommandStorage().set(SurvivalApi.CALENDAR,original);}h.succeed();
    }
    public static void huntPursuit(GameTestHelper h){
        for(var floor:BlockPos.betweenClosed(h.absolutePos(new BlockPos(0,1,0)),h.absolutePos(new BlockPos(7,1,3))))h.getLevel().setBlock(floor,Blocks.STONE.defaultBlockState(),3);
        var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));actor.setNoAi(false);SurvivalApi.enroll(actor);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var quarry=h.spawn(EntityTypes.COW,new BlockPos(6,2,1));quarry.setNoAi(true);float health=quarry.getHealth();
        for(int cx=actor.chunkPosition().x()-2;cx<=actor.chunkPosition().x()+2;cx++)for(int cz=actor.chunkPosition().z()-2;cz<=actor.chunkPosition().z()+2;cz++)h.getLevel().getChunk(cx,cz);
        h.assertTrue(WorldActions.hunt(actor,quarry).success(),"An AI-enabled humanoid must accept a nearby real hunting task");h.runAtTickTime(80,()->{h.assertTrue(!quarry.isAlive()||quarry.getHealth()<health||actor.distanceToSqr(quarry)<9,"Real loaded NPC navigation must close five-block quarry distance or land a physical strike");actor.discard();quarry.discard();h.succeed();});
    }
    private static int finish(net.minecraft.world.entity.LivingEntity actor,int limit){int ticks=0;while(WorldActions.inspectJob(actor).get("active").getAsBoolean()&&ticks<limit){actor.tickCount++;WorldActions.tick(actor);ticks++;}return ticks;}
    private static void patch(GameTestHelper h,BlockPos at){h.getLevel().setBlock(at.below(),Blocks.DIRT.defaultBlockState(),3);h.getLevel().setBlock(at,SurvivalContent.LOOSE_STONES.get().defaultBlockState(),3);}
    public static void foragePractice(GameTestHelper h){
        var novice=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));var expert=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,3));novice.setNoAi(true);expert.setNoAi(true);SurvivalApi.enroll(novice);SurvivalApi.enroll(expert);var learned=SurvivalApi.state(expert);learned.skills.setLevel(Skill.FORAGING,20);SurvivalApi.save(expert,learned);var a=h.absolutePos(new BlockPos(2,2,1));var b=h.absolutePos(new BlockPos(2,2,3));patch(h,a);patch(h,b);
        h.assertTrue(WorldActions.forage(novice,a).success()&&WorldActions.forage(expert,b).success(),"Forage alias must start the same physical patch work for both skill levels");h.assertTrue(SurvivalApi.state(novice).skills.experience(Skill.FORAGING)==0,"Starting forage cannot award experience");int noviceTime=finish(novice,200),expertTime=finish(expert,200);h.assertTrue(noviceTime>expertTime&&h.getLevel().isEmptyBlock(a)&&h.getLevel().isEmptyBlock(b),"Practiced foraging must finish the same real resource work faster");double earned=SurvivalApi.state(novice).skills.experience(Skill.FORAGING);h.assertTrue(earned>0&&SurvivalApi.state(novice).skills.experience(Skill.FARMING)==0,"Completed gathering develops only foraging");h.assertFalse(WorldActions.forage(novice,a).success(),"An exhausted patch cannot be harvested again");for(int i=0;i<100;i++){novice.tickCount++;WorldActions.tick(novice);}h.assertTrue(SurvivalApi.state(novice).skills.experience(Skill.FORAGING)==earned,"Retries and idle ticks cannot repeat completed practice");
        var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess());novice.saveWithoutId(saved);novice.load(net.minecraft.world.level.storage.TagValueInput.create(net.minecraft.util.ProblemReporter.DISCARDING,h.getLevel().registryAccess(),saved.buildResult()));novice.tickCount++;WorldActions.tick(novice);h.assertTrue(SurvivalApi.state(novice).skills.experience(Skill.FORAGING)==earned,"Reloading a completed actor cannot mint another practice award");
        patch(h,a);h.assertTrue(WorldActions.forage(novice,a).success(),"A second actual patch may start");WorldActions.cancel(novice,"Test cancel");h.assertTrue(SurvivalApi.state(novice).skills.experience(Skill.FORAGING)==earned,"Cancelled work cannot grant practice");novice.discard();expert.discard();h.succeed();
    }
    private static void ripe(GameTestHelper h,BlockPos pos){h.getLevel().setBlock(pos.below(),Blocks.FARMLAND.defaultBlockState().setValue(FarmlandBlock.MOISTURE,7),3);h.getLevel().setBlock(pos,Blocks.WHEAT.defaultBlockState().setValue(CropBlock.AGE,7),3);var all=SeasonalCrops.records(h.getLevel());var record=new net.minecraft.nbt.CompoundTag();record.putLong("growth",8*24000L);record.putLong("last",SurvivalApi.calendar(h.getLevel()));record.putBoolean("sown",true);all.put(Long.toString(pos.asLong()),record);SeasonalCrops.save(h.getLevel(),all);}
    public static void farmingParity(GameTestHelper h){
        var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));actor.setNoAi(true);SurvivalApi.enroll(actor);var npcCrop=h.absolutePos(new BlockPos(2,2,1));var nativeCrop=h.absolutePos(new BlockPos(3,2,1));ripe(h,npcCrop);ripe(h,nativeCrop);h.assertTrue(WorldActions.start(actor,"harvest",npcCrop).success(),"NPC ripe crop work must start");finish(actor,200);var player=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);player.setPos(net.minecraft.world.phys.Vec3.atBottomCenterOf(nativeCrop.west()));net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock(player,nativeCrop,net.minecraft.core.Direction.UP,net.neoforged.neoforge.event.entity.player.PlayerInteractEvent.LeftClickBlock.Action.START));finish(player,200);double npc=SurvivalApi.state(actor).skills.experience(Skill.FARMING),human=SurvivalApi.state(player).skills.experience(Skill.FARMING);h.assertTrue(npc>0&&npc==human,"Native and controller harvest must award comparable practice exactly once");h.assertTrue(SurvivalApi.state(actor).skills.experience(Skill.FORAGING)==0,"Sown wheat must train farming rather than wild foraging");actor.discard();h.succeed();
    }
    public static void huntValidation(GameTestHelper h){
        var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));actor.setNoAi(true);SurvivalApi.enroll(actor);var quarry=h.spawn(EntityTypes.COW,new BlockPos(6,2,1));quarry.setNoAi(true);h.assertFalse(WorldActions.hunt(actor,quarry).success(),"Bare hands cannot start a weapon hunting job");actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));float health=quarry.getHealth();h.assertTrue(WorldActions.hunt(actor,quarry).success(),"A physical weapon may begin bounded pursuit");finish(actor,70);h.assertTrue(quarry.getHealth()==health&&actor.getMainHandItem().getDamageValue()==0,"Out-of-reach quarry cannot be damaged or consume attack wear");WorldActions.cancel(actor,"Test cleanup");h.assertTrue(SurvivalApi.state(actor).skills.experience(Skill.HUNTING)==0,"Pursuit and cancellation cannot grant kill practice");
        quarry.setPos(actor.position().add(2,0,0));var wall=actor.blockPosition().east();h.getLevel().setBlock(wall,Blocks.STONE.defaultBlockState(),3);h.getLevel().setBlock(wall.above(),Blocks.STONE.defaultBlockState(),3);h.assertTrue(WorldActions.hunt(actor,quarry).success(),"Blocked quarry may be pursued but cannot be remotely struck");finish(actor,70);h.assertTrue(quarry.getHealth()==health,"Hunting must honor actual line of sight");WorldActions.cancel(actor,"Test cleanup");var body=SurvivalApi.state(actor);body.anatomy[SurvivalState.Part.BRAIN.ordinal()]=0;SurvivalApi.save(actor,body);h.assertFalse(WorldActions.hunt(actor,quarry).success(),"Mental incapacity prevents a hunting job");actor.discard();quarry.discard();h.succeed();
    }
    public static void huntOutcome(GameTestHelper h){
        var actor=h.spawn(EntityTypes.VILLAGER,new BlockPos(1,2,1));actor.setNoAi(true);SurvivalApi.enroll(actor);actor.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.IRON_SWORD));var quarry=h.spawn(EntityTypes.COW,new BlockPos(2,2,1));quarry.setNoAi(true);quarry.setHealth(1);double before=SurvivalApi.state(actor).hunger;h.assertTrue(WorldActions.hunt(actor,quarry).success(),"A supplied nearby hunter must start");h.assertFalse(WorldActions.start(actor,"mine",h.absolutePos(new BlockPos(3,1,1))).success(),"Hunting excludes simultaneous manual field work");int ticks=finish(actor,150);h.assertFalse(quarry.isAlive(),"Completed actual weapon contact must kill the real quarry");h.assertTrue(actor.getMainHandItem().getDamageValue()>0,"A real successful strike must wear the actual weapon");h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,quarry.getBoundingBox().inflate(3),e->e.getItem().is(Items.BEEF)).stream().mapToInt(e->e.getItem().getCount()).sum()>0,"Food must come from the animal's real loot path");double xp=SurvivalApi.state(actor).skills.experience(Skill.HUNTING);h.assertTrue(xp==8.75,"Hunting job must use the shared real-death award exactly once");h.assertTrue(Math.abs(before-SurvivalApi.state(actor).hunger-(.25+ticks*.0005))<1e-6,"A strike pays actual attack hunger once plus loaded manual time");h.assertFalse(WorldActions.hunt(actor,quarry).success(),"Dead quarry cannot be hunted again");finish(actor,50);h.assertTrue(SurvivalApi.state(actor).skills.experience(Skill.HUNTING)==xp,"Repeated commands or ticks cannot duplicate a kill award");actor.discard();h.succeed();
    }
}
